package com.nexustools.genericui.res

/**
 * Typed Android-like resource handle (`R.drawable.ic_brush`, `R.string.app_name`, `RC.drawable.ic_move`, etc.)
 * generated by the GenericUI Gradle plugin (`compileGenericUiResources`) and resolved at runtime via [Resources].
 *
 * - [id]: Android-style `0x7fTTNNNN` numeric resource ID (also mapped to Win32 `.rc` resource IDs).
 * - [type]: The [ResourceType] category (`DRAWABLE`, `STRING`, `COLOR`, `DIMEN`, `RAW`, `FONT`, etc.).
 * - [name]: Snake-case resource identifier (e.g. `"ic_tool_brush"`, `"app_title"`).
 * - [relativePath]: Original relative path inside the project's resources directory.
 */
data class ResourceId(
    val id: Int,
    val type: ResourceType,
    val name: String,
    val relativePath: String = ""
) {
    /**
     * Canonical URI (`"res://drawable/ic_tool_brush"`) understood by all GenericUI native backends.
     */
    fun toResourceUri(): String = "res://${type.directoryName}/$name"

    /**
     * Win32 `.rc` integer resource ID (`1000 + (id and 0xFFFF)`).
     */
    val win32ResourceId: Int
        get() = ((type.typeCode and 0x0F) * 1000) + (id and 0x0FFF)

    override fun toString(): String = toResourceUri()
}
